       (SAMPLE(?area) AS ?catchmentAreaKm2)
WHERE {
  GRAPH <hydroturtle/quadica> {
    ?catchment rdf:type envthes:30212 ;
                geo:hasGeometry ?catchmentGeom .
    ?catchment envthes:30212 ?unused .

    ?station rdf:type sosa:Sensor ;
              geo:hasGeometry ?stationGeom ;
              envthes:30212 ?catchment .

    ?catchment hyobs:hasCatchmentAreaKm2 ?catchmentAreaQv .
    ?catchmentAreaQv qudt:numericValue ?areaQv .
    ?areaQv qudt:numericValue ?area .

    FILTER(datatype(?area) = xsd:decimal || ?area castable as xsd:decimal)
  }
}
GROUP BY ?catchment ?station ?stationGeom
ORDER BY DESC(xsd:decimal(?catchmentAreaKm2))
LIMIT 5

actual_sparql:
PREFIX hyobs:  <https://w3id.org/hmontology/>
PREFIX geo:    <http://www.opengis.net/ont/geosparql#>
PREFIX sosa:   <http://www.w3.org/ns/sosa/>
PREFIX schema: <http://schema.org/>
PREFIX qudt:   <http://qudt.org/schema/qudt/>
PREFIX xsd:    <http://www.w3.org/2001/XMLSchema#>

SELECT ?sensor ?stationName ?catchment ?area ?wkt ?lon ?lat
WHERE {
  GRAPH <hydroturtle/quadica> {
    ?sensor a sosa:Sensor ;
            geo:hasGeometry ?geom;
            hyobs:monitorsCatchment ?catchment .
    OPTIONAL { ?sensor schema:name ?stationName }

    ?catchment hyobs:hasCatchmentArea ?areaNode .

    ?areaNode qudt:numericValue ?area .

    ?geom geo:asWKT ?wkt .
    BIND(bif:st_x(?wkt) AS ?lon)
    BIND(bif:st_y(?wkt) AS ?lat)
  }
}
ORDER BY DESC(xsd:decimal(?area))
LIMIT 5

